class Solution:
    def numberOfSequence(self, n: int, sick: List[int]) -> int:
        MOD = 10**9 + 7
        sick_set = set(sick)
        intervals = []
        prev = -1
        for pos in sick:
            if prev != -1 and pos - prev - 1 > 0:
                intervals.append((prev + 1, pos - 1))
            prev = pos
        if n - 1 not in sick_set:
            if prev != -1 and n - 1 - prev - 1 >= 0:
                intervals.append((prev + 1, n - 1))
            else:
                intervals.append((0, n - 1))

        res = 1
        for (l, r) in intervals:
            length = r - l + 1
            res = res * 2 ** (length - 1) % MOD
        return res
